class Resource extends Vector {
 heading='Layers of somewhere else.';note='A small landscape, cut from light and quiet color.';
 build(){const random=seedRandom(this.number('seed',53,1,100)),layers=this.number('detail',7,3,10),id=this.artId;const colors=['#c9d0b6','#b2c3a4','#9ab497','#7fa18b','#648d7e','#487669','#305c55','#224941','#1b3a35','#142e2b'];let shapes='';for(let layer=0;layer<layers;layer++){let points=`M20 400V${(110+layer*27).toFixed(1)}`;const phase=random()*6,amplitude=25+random()*35;for(let x=20;x<=700;x+=8){const y=110+layer*(220/layers)+Math.sin(x/135+phase)*amplitude+Math.sin(x/61+phase)*amplitude*.25;points+=`L${x} ${y.toFixed(1)}`;}points+='L700 400Z';shapes+=`<path d="${points}" fill="${layer===layers-1?this.color:colors[Math.floor(layer/layers*colors.length)]}" stroke="#fff" stroke-opacity=".1" stroke-width=".8"/>`;}
 return this.svg(`<defs><linearGradient id="${id}-sky" x2="0" y2="1"><stop stop-color="#ddd7bc"/><stop offset="1" stop-color="#abbca8"/></linearGradient><clipPath id="${id}-window"><rect x="20" y="20" width="680" height="380" rx="150"/></clipPath></defs><g clip-path="url(#${id}-window)"><rect x="20" y="20" width="680" height="380" fill="url(#${id}-sky)"/><circle cx="${450+random()*100}" cy="100" r="43" fill="#f3e9c5"/>${shapes}<path d="M500 90q8-8 16 0m2-3q7-7 14 0" fill="none" stroke="#5b746a66"/></g><text x="360" y="414" text-anchor="middle" fill="#98a58c" font-family="monospace" font-size="8" letter-spacing="3">AN IMAGINED PLACE / ${layers} LAYERS</text>`);}
}
